import {STATUSES,TITLES,PRESET_VERSION,blankProfile,safeURL,normalizeJob,mergeJobs,matchJob,researchReady,buildPrompt,validateResume,escapeHTML as e,resumeHTML} from './core.js';
import {download,createDocx} from './export.js';
const STORAGE='applydesk.workspace.v1',root=document.querySelector('#app');
let state={version:1,profile:blankProfile(),jobs:[]},page='dashboard',selected=null,tab='research',query='',filter='All',eligibility='All',fullResume=false,master='';
let storageError='';try{const saved=localStorage.getItem(STORAGE);if(saved){const x=JSON.parse(saved);if(x.version===1&&Array.isArray(x.jobs)&&x.profile)state={...x,jobs:x.jobs.filter(j=>j.source!=='Fictional demo')};else storageError='An incompatible workspace was found. Export or restore a compatible backup.';}}catch{storageError='Browser storage is unavailable or damaged. Export a backup before closing this page.';}
try{const r=await fetch('./prompts/master-resume.txt');if(!r.ok)throw Error();master=await r.text();}catch{storageError+=' The master preset could not be loaded. Reload before generating a prompt.';}
const $=s=>document.querySelector(s),val=id=>document.getElementById(id)?.value??'',job=()=>state.jobs.find(x=>x.id===selected);
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),5000);}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state));return true;}catch{toast('Storage is full or unavailable. Export a backup now.');return false;}}
function go(next){page=next;render();window.scrollTo(0,0);}
function date(s){return s?new Date(s).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}):'Unknown';}
function button(text,action,extra=''){return `<button data-action="${action}" ${extra}>${text}</button>`;}
function field(id,label,value='',type='text',extra=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${e(value)}" ${extra}></div>`;}
function area(id,label,value='',extra=''){return `<div class="field"><label for="${id}">${label}</label><textarea id="${id}" ${extra}>${e(value)}</textarea></div>`;}
function select(id,label,options,value){return `<div class="field"><label for="${id}">${label}</label><select id="${id}">${options.map(o=>`<option ${o===value?'selected':''}>${e(o)}</option>`).join('')}</select></div>`;}
function heading(title,description,actions=''){return `<div class="heading"><div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
function sortedJobs(){return [...state.jobs].filter(j=>(filter==='All'||j.status===filter)&&(eligibility==='All'||matchJob(j,state.profile).eligibility===eligibility)&&`${j.title} ${j.company} ${j.location}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>matchJob(b,state.profile).score-matchJob(a,state.profile).score);}
function card(j){const m=matchJob(j,state.profile);return `<article class="jobcard"><div class="jobtop"><div><button class="jobtitle" data-job="${e(j.id)}">${e(j.title)}</button><div class="jobmeta">${e(j.company)}<br>${e(j.location)} · ${e(j.mode)}</div></div><div class="score">${m.score}<small>priority</small></div></div><div class="tags"><span class="tag ${m.eligibility.toLowerCase()}">${m.eligibility}</span><span class="tag">${e(j.status)}</span><span class="tag">Posted: ${date(j.postedAt)}</span></div></article>`;}
function empty(){return `<div class="empty"><h3>Your next opportunity starts here</h3><p>Save a job description to compare it with your skills and prepare a tailored application.</p>${button('Save your first job','add','class="primary"')}</div>`;}
function dashboard(){const active=state.jobs.filter(j=>!['Archived','Rejected'].includes(j.status)),eligible=active.filter(j=>matchJob(j,state.profile).eligibility==='Eligible');return heading('Your application workspace','A focused search. A thoughtful application.',button('+ Save a job','add','class="primary"'))+`<div class="stats"><div class="stat"><span>Saved opportunities</span><b>${active.length}</b><span>In your workspace</span></div><div class="stat"><span>Location eligible</span><b>${eligible.length}</b><span>Review skills before applying</span></div><div class="stat"><span>Applications sent</span><b>${state.jobs.filter(j=>j.status==='Applied').length}</b><span>Manually confirmed by you</span></div><div class="stat"><span>Interview stage</span><b>${state.jobs.filter(j=>j.status==='Interview').length}</b><span>Keep your notes together</span></div></div><div class="workgrid"><section class="panel"><div class="panel-title"><h2>Worth a closer look</h2>${button('View all jobs','jobs','class="pill-btn"')}</div><p class="muted">A transparent priority score, not an ATS score or a hiring prediction.</p>${active.length?active.sort((a,b)=>matchJob(b,state.profile).score-matchJob(a,state.profile).score).slice(0,4).map(card).join(''):empty()}</section><aside><div class="panel"><div class="section-label">YOUR SEARCH FOCUS</div><h2>Islamabad. Rawalpindi.<br>Remote from Pakistan.</h2><p class="muted">DevOps, cloud and AI/ML. Internships, graduate and associate opportunities.</p><div class="tags"><span class="tag">Up to 100 km discovery</span><span class="tag">Entry-level</span></div><div class="links">${button('Open search planner','search','class="pill-btn"')}</div></div><div class="panel"><h2>A repeatable routine</h2>${[['Save your real experience','One profile becomes the source for every tailored draft.'],['Capture a promising job','Review the location, requirements and original listing.'],['Research, tailor, review','Save your sources and check every claim before exporting.'],['Apply and keep track','Submit on the employer site yourself, then update the status.']].map((s,i)=>`<div class="step"><span class="num">${i+1}</span><div><b>${s[0]}</b><p>${s[1]}</p></div></div>`).join('')}</div></aside></div>`;}
function jobsPage(){return heading('Saved jobs','Keep the description, research and application in one place.',button('+ Save a job','add','class="primary"'))+`<div class="filters"><input id="search-jobs" aria-label="Search saved jobs" placeholder="Search titles, companies or locations" value="${e(query)}"><select id="status-filter" aria-label="Filter by application status">${['All',...STATUSES].map(o=>`<option ${o===filter?'selected':''}>${o}</option>`).join('')}</select><select id="eligibility-filter" aria-label="Filter by location eligibility">${['All','Eligible','Review','Excluded'].map(o=>`<option ${o===eligibility?'selected':''}>${o}</option>`).join('')}</select></div><div id="job-results">${sortedJobs().length?sortedJobs().map(card).join(''):empty()}</div>`;}
function profilePage(){const p=state.profile;return heading('Your verified profile','Write this once. Keep every future draft grounded in it.',button('Save profile','save-profile','class="primary"'))+`<div class="notice">Your details stay in this browser unless you download a backup or deliberately send a generation prompt to a provider. No resume is required to try the product. Do not enter passwords or identity document numbers.</div><div class="panel formgrid">${field('name','Name',p.name)}${field('contact','Contact line and public portfolio links',p.contact)}<div class="full">${area('skills','Verified skills, one per line or separated by commas',p.skills,'placeholder="Only skills you can honestly discuss in an interview"')}${area('experience','Real work history: official title, employer, dates, responsibilities and evidence',p.experience,'placeholder="Do not turn coursework into employment. If you have no work experience, say that explicitly."')}${area('education','Education and real certifications',p.education)}${area('projects','Real projects: what you built, your contribution, tools and evidence links',p.projects)}${area('preferences','Search and writing preferences',p.preferences)}</div></div><div class="notice warn">Changing this profile marks saved documents for a fresh review. Your original master preset is kept separately and never rewritten.</div>`;}
function searchPage(){return heading('Search planner','Open one focused search at a time, then save worthwhile roles.','<a href="https://pk.indeed.com/" target="_blank" rel="noopener noreferrer">Open Indeed Pakistan ↗</a>')+`<div class="notice">Set the site’s distance control to at most 100 km and sort by newest. A 100 km search can include other towns; the default acceptance rule remains Islamabad and Rawalpindi. For remote jobs, check Pakistan eligibility, work authorization and time zones.</div><div class="search-list">${TITLES.map(t=>`<div class="search-item"><h3>${e(t)}</h3>${['Islamabad','Rawalpindi','Remote'].map(l=>`<a target="_blank" rel="noopener noreferrer" href="https://pk.indeed.com/jobs?q=${encodeURIComponent(t)}&l=${encodeURIComponent(l)}">${l} ↗</a>`).join('')}</div>`).join('')}</div><div class="panel"><h2>Daily search order</h2><p>Start with DevOps and cloud internships. Search associate and junior titles next. Then review AI/ML and MLOps roles. Create native job alerts on sites that offer them, and check employer career pages for current details.</p><p class="muted">These links open human-operated searches. The app does not scrape Indeed, access your account or submit applications. Check the actual radius and remote filters on Indeed; URL parameters are not treated as proof of those settings.</p></div>`;}
function addPage(){return heading('Save an opportunity','Paste the full description. Keep the original link for your final review.')+`<form id="job-form" class="panel formgrid">${field('title','Job title','','text','required maxlength="200"')}${field('company','Company','','text','required maxlength="200"')}${field('url','Original job URL','','url','required')}${field('location','Location','','text','required')}${select('mode','Work arrangement',['On-site','Hybrid','Remote'],'On-site')}${select('remoteEligibility','Remote eligibility',['Unknown','Pakistan','Worldwide','Restricted'],'Unknown')}${field('postedAt','Date posted (leave blank if unknown)','','date')}${field('deadline','Application deadline (optional)','','date')}${field('minYears','Minimum required years (optional)','','number','min="0" max="50"')}${field('source','Source','Manual')}<div class="full">${area('description','Full job description','','required maxlength="50000"')}<div class="actions"><button class="primary" type="submit">Save job</button><button type="button" data-action="jobs">Cancel</button></div></div></form>`;}
function researchPanel(j){return `<div class="split"><section class="panel"><h2>Company research</h2><p class="muted">Use the official company and careers pages. Verify the company identity, products and role priorities. Record facts separately from reasonable role-related inferences.</p><div class="links"><a href="https://www.google.com/search?q=${encodeURIComponent(j.company+' official website careers')}" target="_blank" rel="noopener noreferrer">Find official sources ↗</a></div><form id="research-form">${field('source-url','Source URL','','url','required')}${area('source-notes','Facts and relevance to this vacancy','','required placeholder="Facts: ...\nRole-related inference: ..."')}<label class="checkrow"><input type="checkbox" id="source-verified" required>I opened this source, checked the company identity and verified these notes.</label><button type="submit" class="primary">Save research source</button></form></section><section class="panel"><h2>Evidence notebook</h2>${j.research.length?j.research.map((r,i)=>`<div class="source"><a href="${e(safeURL(r.url))}" target="_blank" rel="noopener noreferrer">${e(new URL(r.url).hostname)} ↗</a><div class="source-date">Checked ${date(r.checkedAt)} · ${r.verified?'Confirmed by you':'Unverified'}</div><p>${e(r.notes)}</p><button class="pill-btn" data-remove-source="${i}">Remove source</button></div>`).join(''):'<p class="muted">No sources yet. Research is required before a company-specific draft can claim “After researching”.</p>'}<div class="notice ${researchReady(j)?'good':'warn'}">${researchReady(j)?'Recent user-verified research is available. The app has not independently browsed or verified these facts.':'Add or refresh a source before generating. Notes older than 30 days require another check.'}</div></section></div>`;}
function documentText(j,kind){let s=j[kind]||'';if(kind==='resume'&&fullResume){const p=state.profile;s=[p.name,p.contact,'',s,p.education?'\nEDUCATION\n'+p.education:'',p.projects?'\nPROJECTS\n'+p.projects:''].filter(Boolean).join('\n');}return s;}
function paper(j,kind){return `<article class="paper">${resumeHTML(documentText(j,kind))||'<p>Your formatted document will appear here after you paste or generate a draft.</p>'}</article>`;}
function docPanel(j,kind){const resume=kind==='resume',text=j[kind]||'',v=resume?validateResume(text,j):{errors:!text.trim()?['Add a cover letter draft.']:/—/.test(text)?['Remove em dashes.']:[],warnings:['Check names, company facts and every claim against your profile.']};return `<div class="notice">Free path: build the prompt, use it in your own AI chat with browsing, then paste the finished ${resume?'three resume sections':'cover letter'} below. Local generation is optional and needs Ollama running on your computer. This public site does not include a paid AI API.</div><div class="actions">${button('Copy generation prompt','copy-prompt','class="primary"')}${button('Download prompt','download-prompt')}${button('Generate with local Ollama','generate')}<span class="muted">${resume?'Exact master preset '+PRESET_VERSION:'Separate cover letter preset'}</span></div><div class="split"><section class="panel">${area('draft',resume?'Resume sections (Markdown)':'Cover letter draft',text,'class="editor"')}<div class="actions">${button('Save draft version','save-draft','class="primary"')}${button('Check formatting','check-draft')}</div><p class="muted">Typing is saved automatically. Save a draft version to create a named point in history.</p>${resume?`<label class="checkrow"><input type="checkbox" id="full-resume" ${fullResume?'checked':''}>Full resume export: add my name, contact details, education and projects around these three sections. The preset’s sections-only mode stays available.</label>`:''}<label class="checkrow"><input type="checkbox" id="reviewed" ${j.reviewed?'checked':''}>I checked the current resume and cover letter against my real experience and sources, and removed unsupported claims.</label><div id="validation">${validationHTML(v)}</div><div class="actions">${button('Download Word (.docx)','docx')}${button('Print / Save as PDF','print')}${button('Download draft (.md)','markdown')}</div><details><summary>Saved versions (${j.versions.length})</summary>${j.versions.map((x,i)=>`<p class="muted">${e(x.kind)} · ${date(x.createdAt)} ${button('Restore','restore-version',`data-version="${i}" class="pill-btn"`)}</p>`).join('')}</details></section><section><div class="panel-title"><h2>Document preview</h2><span class="muted">A4 · Arial · 10/11 pt</span></div><div id="preview">${paper(j,kind)}</div></section></div>`;}
function validationHTML(v){return `<div class="notice ${v.errors.length?'warn':'good'}"><b>${v.errors.length?'Before final export':'Structure checks passed'}</b><ul class="checks">${[...v.errors,...v.warnings].map(x=>`<li>${e(x)}</li>`).join('')}</ul></div>`;}
function detailPage(){const j=job();if(!j){page='jobs';return jobsPage();}const m=matchJob(j,state.profile);return heading(e(j.title),e(j.company)+' · '+e(j.location),button('Back to jobs','jobs'))+`<div class="panel"><div class="formgrid"><div>${select('job-status','Application status',STATUSES,j.status)}</div><div><div class="section-label">Priority ${m.score}/100 · ${m.eligibility}</div><p class="muted">${e([...m.reasons,...m.flags].join(' · '))}</p></div></div><div class="actions">${j.url?`<a href="${e(safeURL(j.url))}" target="_blank" rel="noopener noreferrer">Open original listing ↗</a>`:''}${button('Send this job to Make','make-job','class="pill-btn"')}<span class="muted">First saved ${date(j.firstSeenAt)} · Last seen ${date(j.lastSeenAt)}</span></div><details><summary>Saved job description</summary><div class="detail-description">${e(j.description)}</div></details></div><div class="tabs">${[['research','Company research'],['resume','Tailored resume'],['coverLetter','Cover letter'],['notes','Application notes']].map(([key,label])=>`<button data-tab="${key}" class="${tab===key?'active':''}">${label}</button>`).join('')}</div>${tab==='research'?researchPanel(j):tab==='notes'?`<div class="panel">${area('application-note','Interview, follow-up and submission notes',j.note)}${button('Save notes','save-notes','class="primary"')}<p class="muted">Open listing does not mean Applied. Update the status only after you have submitted successfully yourself.</p></div>`:docPanel(j,tab)}`;}
function tracker(){return heading('Application tracker','Move each opportunity forward when something actually changes.')+`<div class="board">${STATUSES.filter(s=>s!=='Archived').map(s=>`<section class="panel"><h2>${s} <span class="count">${state.jobs.filter(j=>j.status===s).length}</span></h2>${state.jobs.filter(j=>j.status===s).map(card).join('')||'<p class="muted">No jobs at this stage.</p>'}</section>`).join('')}</div>`;}
function automation(){return heading('Automation connections','Keep discovery affordable and keep the final decision with you.')+`<div class="split"><section class="panel"><h2>Make intake</h2><p>Run your configured Make scenario to collect jobs from approved employer feeds. Only a request ID and action are sent. Candidate details are not sent by this intake button.</p>${button('Run Make intake','make-intake','class="primary"')}<div class="notice">Requires the local app and a private MAKE_WEBHOOK_URL setting. On a static Vercel or Netlify demo, use JSON import below. No live Make connection is preconfigured.</div><details><summary>Scenario contract</summary><pre>{"jobs":[{"title":"Cloud Intern","company":"Employer","location":"Islamabad","description":"Full description","url":"https://example.com/job","source":"Approved feed"}]}</pre></details><p class="muted">See the repository’s Make setup guide for the exact module flow, limits and retry behavior.</p></section><section class="panel"><h2>Public employer feed</h2><p class="muted">Optional local adapter. Enter a board token from a real Greenhouse or Lever careers page. Imported remote locations still require review.</p><form id="feed-form">${select('feed-provider','Feed provider',['Greenhouse','Lever'],'Greenhouse')}${field('feed-board','Employer board token','','text','required pattern="[A-Za-z0-9_-]+"')}${field('feed-company','Employer display name','','text','required')}<button type="submit" class="primary">Import published jobs</button></form></section></div><section class="panel"><h2>Import jobs from JSON</h2><p class="muted">Paste an array or an object with a jobs array. Imports merge by canonical URL. Duplicate records keep their application status and documents.</p>${area('import-json','Job data','','placeholder=\'{"jobs": []}\'')}<div class="actions">${button('Import jobs','import-jobs','class="primary"')}</div></section><section class="panel"><h2>What runs where</h2><p><b>This browser:</b> profile, saved jobs, scoring, research notes, formatting, document downloads and backups.</p><p><b>Your local computer:</b> optional Ollama inference and Make/feed adapters. It must be awake and connected for these to run.</p><p><b>Make:</b> your connected scenario and its permitted source requests. Free credits are finite.</p><p><b>Future shared product:</b> Supabase for accounts and isolated user records, with a server-side worker. Neon is an alternative database choice, not a second required database.</p></section>`;}
function settings(){return heading('Data and writing preset','Your profile belongs to you. Keep a backup before clearing browser data.')+`<div class="split"><section class="panel"><h2>Workspace backup</h2><p>Export profile, jobs, research, drafts, versions and notes as JSON. It contains your personal information. Keep it private.</p><div class="actions">${button('Export private backup','backup','class="primary"')}</div><div class="field"><label for="restore-file">Restore a workspace backup</label><input id="restore-file" type="file" accept=".json,application/json"></div><p class="muted">Restoring replaces this browser’s workspace after confirmation. This is a single-device prototype; it does not sync between people or browsers.</p><div class="actions">${button('Clear this workspace','clear','class="danger"')}</div></section><section class="panel"><h2>Original resume preset</h2><p class="muted">The attached master prompt is included unchanged. Extra guardrails and candidate data are appended when you build a generation prompt.</p>${button('Download original preset','master')}<details><summary>Read the complete master prompt</summary><pre>${e(master)}</pre></details><p>Cover letters use their own prompt, with simple English and no em dashes.</p></section></div><div class="notice warn">This version stores data in browser storage, which is not encrypted by the application. Do not use a shared computer for private records. Clearing site data removes the local workspace. No analytics or advertising scripts are included.</div>`;}
function render(){root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="./favicon.svg" alt="">Applydesk</div><nav aria-label="Main navigation">${[['dashboard','Overview'],['jobs','Saved jobs'],['search','Search planner'],['tracker','Applications'],['profile','My profile'],['automation','Automations'],['settings','Data & preset']].map(([key,label])=>`<button data-action="${key}" class="${page===key?'active':''}">${label}</button>`).join('')}</nav><div class="foot"><strong>AI Job Assistant</strong>Personal edition · v0.1<br>Built for a thoughtful job search.<br><a href="https://github.com/muhammadbilaldevops/AI-Job-Assistant-Automation" target="_blank" rel="noopener noreferrer">View project ↗</a></div></aside><main class="main"><div class="topline"><span>WORKSPACE / ${e(page==='detail'?'APPLICATION':page.toUpperCase())}</span><span class="local-pill">Stored on this device</span></div>${storageError?`<div class="notice error">${e(storageError)}</div>`:''}${({dashboard,jobs:jobsPage,profile:profilePage,search:searchPage,add:addPage,detail:detailPage,tracker,automation,settings}[page]||dashboard)()}</main></div>`;}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Prompt copied. Paste it into your chosen AI chat.');}catch{download('generation-prompt.txt',text);toast('Clipboard unavailable. The prompt was downloaded instead.');}}
function generationPrompt(){const j=job();if(!master)throw Error('Master preset unavailable. Reload the app.');if(!state.profile.skills.trim()||!state.profile.experience.trim())throw Error('Add your verified skills and real work history in My profile first. If you have no work experience, state that honestly.');if(!researchReady(j))throw Error('Add a recent verified company source first.');return buildPrompt(master,j,state.profile,tab==='coverLetter'?'cover':'resume');}
function saveVersion(){const j=job();j[tab]=val('draft');j.versions.push({kind:tab,text:j[tab],createdAt:new Date().toISOString(),preset:PRESET_VERSION,profileSnapshot:structuredClone(state.profile),researchSnapshot:structuredClone(j.research),jobDescription:j.description});j.reviewed=false;if(persist())toast('Draft version saved. Review this version before final export.');render();}
function exportGuard(){const j=job();j[tab]=val('draft');if(!j.reviewed)throw Error('Confirm that you reviewed the current documents and their facts.');if(!researchReady(j))throw Error('Refresh the company research before final export.');const errors=tab==='resume'?validateResume(j.resume,j).errors:!j.coverLetter.trim()?['Add a cover letter.']:j.coverLetter.includes('—')?['Remove em dashes.']:[];if(errors.length)throw Error(errors[0]);if(fullResume&&tab==='resume'&&(!state.profile.name||!state.profile.contact))throw Error('Add name and contact details for a full resume.');return documentText(j,tab);}
function filename(ext){const j=job();return `${j.company}-${j.title}-${tab}`.replace(/[^a-zA-Z0-9_-]+/g,'-').slice(0,110)+'.'+ext;}
async function api(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.headers.get('content-type')?.includes('application/json'))throw Error('This adapter requires the local app. See the setup guide in the repository.');const x=await r.json();if(!r.ok)throw Error(x.error||'The adapter failed.');return x;}
root.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;try{if(b.dataset.job){selected=b.dataset.job;tab='research';go('detail');return;}if(b.dataset.tab){tab=b.dataset.tab;render();return;}if(b.dataset.removeSource!==undefined){job().research.splice(Number(b.dataset.removeSource),1);job().reviewed=false;persist();render();return;}const a=b.dataset.action;if(!a)return;if(['dashboard','jobs','search','tracker','profile','automation','settings','add'].includes(a)){go(a);return;}
 if(a==='save-profile'){const p={};for(const k of Object.keys(blankProfile()))p[k]=val(k);state.profile=p;state.jobs.forEach(j=>j.reviewed=false);if(persist())toast('Profile saved. Existing drafts need a fresh fact review.');}
 if(a==='copy-prompt')await copy(generationPrompt());
 if(a==='download-prompt')download(filename('prompt.txt'),generationPrompt());
 if(a==='save-draft')saveVersion();
 if(a==='check-draft'){job()[tab]=val('draft');persist();render();toast('Structure checked. Review facts separately.');}
 if(a==='generate'){const prompt=generationPrompt(),targetJob=job(),targetKind=tab;b.disabled=true;b.textContent='Generating locally…';const x=await api('/api/generate',{prompt});targetJob[targetKind]=x.text;targetJob.reviewed=false;persist();if(job()?.id===targetJob.id&&tab===targetKind)render();toast('Local draft received. Review its structure and every fact.');}
 if(a==='markdown')download(filename('md'),documentText(job(),tab));
 if(a==='docx')download(filename('docx'),createDocx(exportGuard()));
 if(a==='print'){const text=exportGuard();document.querySelector('.print-only')?.remove();const p=document.createElement('div');p.className='print-only';p.innerHTML=`<article class="paper">${resumeHTML(text)}</article>`;document.body.append(p);window.print();}
 if(a==='restore-version'){const v=job().versions[Number(b.dataset.version)];job()[v.kind]=v.text;job().reviewed=false;tab=v.kind;persist();render();}
 if(a==='save-notes'){job().note=val('application-note');persist();toast('Application notes saved.');}
 if(a==='backup')download('applydesk-private-backup.json',JSON.stringify(state,null,2),'application/json');
 if(a==='master')download('master-resume-original.txt',master);
 if(a==='clear'&&confirm('Clear this browser workspace? Download a private backup first if you want to restore it later.')){state={version:1,profile:blankProfile(),jobs:[]};persist();go('dashboard');}
 if(a==='import-jobs'){const x=JSON.parse(val('import-json'));const list=Array.isArray(x)?x:x.jobs;if(!Array.isArray(list)||list.length>500)throw Error('Import up to 500 jobs at a time.');const r=mergeJobs(state.jobs,list);state.jobs=r.jobs;persist();toast(`${r.added} jobs added; ${r.updated} duplicates refreshed.`);go('jobs');}
 if(a==='make-job'){const j=job();if(!j.url)throw Error('Add an original listing URL before sending a job to Make.');b.disabled=true;const x=await api('/api/make',{jobs:[{title:j.title,company:j.company,url:j.url,description:j.description,location:j.location,mode:j.mode,remoteEligibility:j.remoteEligibility,postedAt:j.postedAt,source:j.source}]});if(!Array.isArray(x.jobs)||x.jobs.length>500)throw Error('Make must return a jobs array.');const r=mergeJobs(state.jobs,x.jobs);state.jobs=r.jobs;persist();render();toast('Make returned the job batch. Review the refreshed records.');}
 if(a==='make-intake'){b.disabled=true;const x=await api('/api/make',{});if(!Array.isArray(x.jobs)||x.jobs.length>500)throw Error('Make must return an object with a jobs array, up to 500 records.');const r=mergeJobs(state.jobs,x.jobs);state.jobs=r.jobs;persist();toast(`${r.added} jobs added from Make.`);go('jobs');}
 }catch(err){toast(err.message||'Something went wrong.');b.disabled=false;if(b.dataset.action==='generate')b.textContent='Generate with local Ollama';}});
root.addEventListener('submit',async ev=>{ev.preventDefault();try{if(ev.target.id==='job-form'){const x={};for(const key of ['title','company','url','location','mode','remoteEligibility','postedAt','deadline','minYears','source','description'])x[key]=val(key);const r=mergeJobs(state.jobs,[x]);state.jobs=r.jobs;persist();toast(r.added?'Job saved.':'Existing job refreshed.');go('jobs');}
 if(ev.target.id==='research-form'){job().research.push({url:safeURL(val('source-url')),notes:val('source-notes'),verified:$('#source-verified').checked,checkedAt:new Date().toISOString()});job().reviewed=false;persist();render();}
 if(ev.target.id==='feed-form'){const b=ev.target.querySelector('button');b.disabled=true;try{const x=await api('/api/feed',{provider:val('feed-provider'),board:val('feed-board'),company:val('feed-company')});const r=mergeJobs(state.jobs,x.jobs);state.jobs=r.jobs;persist();toast(`${r.added} published jobs imported. Review eligibility.`);go('jobs');}finally{b.disabled=false;}}
 }catch(err){toast(err.message);}});
root.addEventListener('input',ev=>{if(ev.target.id==='search-jobs'){query=ev.target.value;$('#job-results').innerHTML=sortedJobs().map(card).join('')||'<div class="empty">No jobs match these filters.</div>';}
 if(ev.target.id==='draft'){job()[tab]=ev.target.value;job().reviewed=false;const review=$('#reviewed');if(review)review.checked=false;persist();$('#preview').innerHTML=paper(job(),tab);}
 if(ev.target.id==='application-note'){job().note=ev.target.value;persist();}});
root.addEventListener('change',async ev=>{try{const id=ev.target.id;if(id==='status-filter'){filter=ev.target.value;render();}if(id==='eligibility-filter'){eligibility=ev.target.value;render();}if(id==='job-status'){job().status=ev.target.value;job().statusUpdatedAt=new Date().toISOString();persist();toast('Application status updated.');}if(id==='reviewed'){job().reviewed=ev.target.checked;persist();}if(id==='full-resume'){fullResume=ev.target.checked;$('#preview').innerHTML=paper(job(),tab);}if(id==='restore-file'){const f=ev.target.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('Backup exceeds 10 MB.');const x=JSON.parse(await f.text());if(x.version!==1||!Array.isArray(x.jobs)||x.jobs.length>5000||!x.profile||Object.keys(blankProfile()).some(k=>typeof x.profile[k]!=='string'))throw Error('This is not a compatible workspace backup.');const restored=x.jobs.map(j=>{const n=normalizeJob(j);if(!STATUSES.includes(j.status)||!Array.isArray(j.research)||!Array.isArray(j.versions))throw Error('Backup contains invalid job records.');return {...n,id:n.id,status:j.status,firstSeenAt:j.firstSeenAt||n.firstSeenAt,lastSeenAt:j.lastSeenAt||n.lastSeenAt,note:String(j.note||''),resume:String(j.resume||''),coverLetter:String(j.coverLetter||''),research:j.research.filter(r=>safeURL(r.url)&&typeof r.notes==='string'),versions:j.versions.filter(v=>['resume','coverLetter'].includes(v.kind)&&typeof v.text==='string'),reviewed:false};});if(confirm('Replace this browser workspace with the selected backup?')){state={version:1,profile:x.profile,jobs:restored};persist();render();toast('Backup restored. Review documents again before final export.');}}}catch(err){toast(err.message);}});
render();
// Progressive agent support: normal UI remains fully usable without WebMCP.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const registrations=[
  {name:'open_job_search_planner',title:'Open job search planner',description:'Open the assistant search planner. This does not access Indeed or run a search.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{go('search');return {screen:'Search planner',externalSearchStarted:false};}},
  {name:'list_saved_job_summaries',title:'List saved jobs',description:'Read summaries of jobs already saved in this browser workspace. Does not search job boards or return candidate profile data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({jobs:state.jobs.map(j=>({id:j.id,title:j.title,company:j.company,url:j.url,status:j.status,eligibility:matchJob(j,state.profile).eligibility}))})},
  {name:'save_real_job',title:'Save a real job',description:'Save a user-supplied real listing to this browser workspace. Requires the actual source URL and full description. Does not fetch the page, contact the employer, or submit an application.',inputSchema:{type:'object',properties:{title:{type:'string'},company:{type:'string'},url:{type:'string'},description:{type:'string'},location:{type:'string'},mode:{type:'string',enum:['On-site','Hybrid','Remote']},remoteEligibility:{type:'string',enum:['Unknown','Pakistan','Worldwide','Restricted']}},required:['title','company','url','description','location'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||!safeURL(input.url))throw Error('A valid source URL is required.');const result=mergeJobs(state.jobs,[{...input,source:'User-authorized agent intake'}]);state.jobs=result.jobs;if(!persist())throw Error('Could not persist the record. Export a backup.');go('jobs');return {added:result.added,updated:result.updated,submittedApplication:false};}}
 ];
 for(const tool of registrations)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
